/** True when modelKey denotes Supertonic 3 (not legacy Supertonic bundles). */
export function isSupertonic3ModelKey(modelKey: string | undefined): boolean {
  if (!modelKey?.trim()) return false;
  const lower = modelKey.trim().toLowerCase();
  if (!lower.includes('supertonic')) return false;
  return (
    lower.includes('supertonic-3') ||
    lower.includes('supertonic_3') ||
    lower.includes('supertonic-v3') ||
    /supertonic3(?:[_\-.]|$)/.test(lower)
  );
}

export function iso6391HintsForTtsModelType(
  modelType: string | undefined,
  modelKey?: string
): string[] | undefined {
  if (!modelType) return undefined;
  switch (modelType) {
    case 'pocket':
      return [...POCKET_TTS_ISO6391_HINTS];
    case 'supertonic':
      if (isSupertonic3ModelKey(modelKey)) {
        return [...SUPERTONIC3_TTS_ISO6391_HINTS];
      }
      return [...SUPERTONIC_TTS_ISO6391_HINTS];
    default:
      return undefined;
  }
}

const STT_ENTRIES: Readonly<Record<string, readonly ModelLanguage[]>> = {
  whisper: WHISPER_LANGUAGES,
  sense_voice: SENSEVOICE_LANGUAGES,
  canary: CANARY_LANGUAGES,
  funasr_nano: FUNASR_NANO_ENTRIES,
  qwen3_asr: QWEN3_ASR_LANGUAGES,
  cohere_transcribe: COHERE_TRANSCRIBE_LANGUAGES,
  dolphin: DOLPHIN_INFO_LANGUAGES,
};

export function sttModelLanguagesForModelType(
  modelType: string | undefined
): readonly ModelLanguage[] | undefined {
  if (!modelType) return undefined;
  return STT_ENTRIES[modelType];
}

export function iso6391HintsForSttModelType(
  modelType: string | undefined
): string[] | undefined {
  if (!modelType) return undefined;
  const hints = STT_HINTS[modelType];
  return hints ? [...hints] : undefined;
}

